/*
* Requires $vars.slackWebhookUrl to be set in Flowise.
*/

const fetch = require('node-fetch');
const webhookUrl = $vars.slackWebhookUrl;

if (!webhookUrl) {
    throw new Error('Set $vars.slackWebhookUrl before using this tool.');
}

const payload = { text: $message } ;

const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
});

if (!response.ok) {
    const text = await response.text();
    throw new Error(`Slack webhook error: ${response.status} ${text}`);
}

return 'Message delivered to Slack.';
